sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //return trigger by status used in on load , on change client scripts 
        g_scratchpad.triggerby = current.trade_case_id.triggered_by.status.toString();
        g_scratchpad.owningBus = current.trade_id.owning_business.toString();
        g_scratchpad.trdSourceSystem = current.trade_id.source_system.toString();
        g_scratchpad.settlementDate = current.trade_id.settlement_date;
        g_scratchpad.settlementCurrency = current.trade_id.settlement_amount_currency.code;
        // MSSCUSTODY - 4763 - Added new fields for GCS
        g_scratchpad.gcsContractType = current.trade_id.contract_type.toString();
        g_scratchpad.gcsTransactionType = current.trade_id.transaction_type.toString();
        g_scratchpad.gcsFxLocation = current.trade_id.fx_location.toString();
        var gcsSourceSystem = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_swift_gcs');
        g_scratchpad.validSourceSystemGCS = false;
        var sourceSystem = g_scratchpad.trdSourceSystem;
        var owningBusiness = g_scratchpad.owningBus;
        if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (owningBusiness.indexOf('UK') > -1)) {
            g_scratchpad.validSourceSystemGCS = true;
        }
		g_scratchpad.tskoutcome = current.outcome; // MSSCUSTODY-7419

		//MSSCUSTODY-6529
        var amendEnabledMarkets = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedamend.market');
        if (amendEnabledMarkets.indexOf(owningBusiness) > -1) {
            g_scratchpad.validAmendMarket = true;
        } else {
            g_scratchpad.validAmendMarket = false;
        }

        var gcsSourceSystemUK = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGCSWidgetTriggerSourceSystem');
        g_scratchpad.validSourceSystemUK = false;
        if ((gcsSourceSystemUK.indexOf(sourceSystem) > -1)) {
            g_scratchpad.validSourceSystemUK = sourceSystem;
        }
        //g_scratchpad.trade_id.switch_indicator = current.trade_id.switch_indicator; // for 5196



        //Amendment Checker Counter
        g_scratchpad.tradeTaskType = current.trade_task_type.toString(); //MSSCUSTODY-7157
        var tradeID = current.trade_id.sys_id;
        var caseID = current.trade_case_id.sys_id;
        var taskTemplate = current.trade_task_template_id.getDisplayValue();

        g_scratchpad.trdLifeCycle = current.trade_id.legacy_status.toString();
        g_scratchpad.trdSubStatus = current.trade_id.legacy_sub_status.toString();

        g_scratchpad.multipleChecker = false;

        var getChecker = new GlideAggregate("x_hsb11_mss_c_proc_mss_custody_task_passive");
        getChecker.addEncodedQuery('trade_id.sys_idSTARTSWITH' + tradeID + '^trade_case_id.sys_idSTARTSWITH' + caseID + '^trade_task_type=Checker');
        getChecker.groupBy('trade_task_type');
        getChecker.addAggregate('COUNT', 'number');
        getChecker.query();
        while (getChecker.next()) {
            var checkerCounter = parseInt(getChecker.getAggregate('COUNT', 'number'));

        }
        if (checkerCounter > 1) {
            g_scratchpad.multipleChecker = true;
        }

        //Amendement Checker Counter




        //Extra outcome for Maker (Amend) - Review and Close the Task

        var getTemplate = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping');
        getTemplate.addEncodedQuery('trade_template_id.template_idSTARTSWITH' + taskTemplate + '^outcomeLIKEamend');
        getTemplate.query();

        g_scratchpad.multipleMaker = false;

        if (getTemplate.next()) {
            var getMaker = new GlideAggregate("x_hsb11_mss_c_proc_mss_custody_task_passive");
            getMaker.addEncodedQuery('trade_id.sys_idSTARTSWITH' + tradeID + '^trade_case_id.sys_idSTARTSWITH' + caseID + '^trade_task_type=Maker');
            getMaker.groupBy('trade_task_type');
            getMaker.addAggregate('COUNT', 'number');
            getMaker.query();
            while (getMaker.next()) {
                var makerCounter = parseInt(getMaker.getAggregate('COUNT', 'number'));
                if (makerCounter > 1) {
                    g_scratchpad.multipleMaker = true;
                }

            }
        }

        //Extra outcome for Maker (Amend) - Review and Close the Task



    } catch (ex) {
        gs.info('Error Recieved for HSBC -Get Trigger by status ' + ex);
    }

})(current, previous);
